import * as React from "react"
import { Select as SelectPrimitive } from "@base-ui-components/react/select"
import { cva, type VariantProps } from "class-variance-authority"
import { Check, ChevronDown } from "lucide-react"

import { cn } from "@/lib/utils"
import "./select.css"

/* ------------------------------------------------------------------ */
/*  CVA                                                                */
/* ------------------------------------------------------------------ */

const selectTriggerVariants = cva(
  "select-trigger inline-flex items-center justify-between gap-[var(--layout-gap-md)] rounded-[var(--layout-radius-lg)] px-[var(--layout-padding-md)] text-content-note font-accent",
  {
    variants: {
      variant: {
        default: "",
        destructive: "select-trigger-destructive",
        success: "select-trigger-success",
      },
      size: {
        sm: "h-[var(--layout-size-lg)]",
        md: "h-9",
        lg: "h-[var(--layout-size-xl)]",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "md",
    },
  }
)

/* ------------------------------------------------------------------ */
/*  Select                                                             */
/* ------------------------------------------------------------------ */

function Select<Value>(
  props: React.ComponentProps<typeof SelectPrimitive.Root<Value, false>>
) {
  return <SelectPrimitive.Root {...props} />
}

/* ------------------------------------------------------------------ */
/*  SelectGroup                                                        */
/* ------------------------------------------------------------------ */

function SelectGroup({
  ...props
}: React.ComponentProps<typeof SelectPrimitive.Group>) {
  return <SelectPrimitive.Group data-slot="select-group" {...props} />
}

/* ------------------------------------------------------------------ */
/*  SelectValue                                                        */
/* ------------------------------------------------------------------ */

function SelectValue({
  placeholder,
  children,
  ...props
}: Omit<React.ComponentProps<typeof SelectPrimitive.Value>, "children"> & {
  placeholder?: React.ReactNode
  children?: React.ReactNode | ((value: unknown) => React.ReactNode)
}) {
  return (
    <SelectPrimitive.Value data-slot="select-value" {...props}>
      {children !== undefined
        ? (children as React.ComponentProps<typeof SelectPrimitive.Value>["children"])
        : (value: unknown) =>
            value === null || value === undefined || value === ""
              ? placeholder
              : (value as React.ReactNode)}
    </SelectPrimitive.Value>
  )
}

/* ------------------------------------------------------------------ */
/*  SelectTrigger                                                      */
/* ------------------------------------------------------------------ */

function SelectTrigger({
  className,
  variant,
  size,
  children,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.Trigger> &
  VariantProps<typeof selectTriggerVariants>) {
  return (
    <SelectPrimitive.Trigger
      data-slot="select-trigger"
      className={cn(selectTriggerVariants({ variant, size, className }))}
      {...props}
    >
      {children}
      <SelectPrimitive.Icon
        render={
          <ChevronDown className="select-chevron h-[var(--layout-size-xs)] w-[var(--layout-size-xs)] shrink-0" />
        }
      />
    </SelectPrimitive.Trigger>
  )
}

/* ------------------------------------------------------------------ */
/*  SelectContent                                                      */
/* ------------------------------------------------------------------ */

function SelectContent({
  className,
  sideOffset = 6,
  side,
  align,
  children,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.Popup> & {
  sideOffset?: number
  side?: React.ComponentProps<typeof SelectPrimitive.Positioner>["side"]
  align?: React.ComponentProps<typeof SelectPrimitive.Positioner>["align"]
  position?: "popper" | "item-aligned"
}) {
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Positioner
        sideOffset={sideOffset}
        side={side}
        align={align}
        className="z-50"
      >
        <SelectPrimitive.Popup
          data-slot="select-content"
          className={cn(
            "select-content min-w-[var(--anchor-width)] rounded-[var(--layout-radius-xl)] p-[var(--layout-padding-xs)] transition-[opacity,transform] duration-150 data-[starting-style]:opacity-0 data-[starting-style]:scale-95 data-[ending-style]:opacity-0 data-[ending-style]:scale-95 max-h-[var(--available-height)] overflow-y-auto",
            className
          )}
          {...props}
        >
          {children}
        </SelectPrimitive.Popup>
      </SelectPrimitive.Positioner>
    </SelectPrimitive.Portal>
  )
}

/* ------------------------------------------------------------------ */
/*  SelectItem                                                         */
/* ------------------------------------------------------------------ */

function SelectItem({
  className,
  children,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.Item>) {
  return (
    <SelectPrimitive.Item
      data-slot="select-item"
      className={cn(
        "select-item flex items-center gap-[var(--layout-gap-md)] rounded-[var(--layout-radius-lg)] h-9 py-[var(--layout-padding-sm)] px-[var(--layout-padding-md)] text-content-note font-accent",
        className
      )}
      {...props}
    >
      <SelectPrimitive.ItemText className="flex-1">{children}</SelectPrimitive.ItemText>
      <SelectPrimitive.ItemIndicator className="select-item-indicator shrink-0 ml-auto">
        <Check className="h-[var(--layout-size-xs)] w-[var(--layout-size-xs)]" />
      </SelectPrimitive.ItemIndicator>
    </SelectPrimitive.Item>
  )
}

/* ------------------------------------------------------------------ */
/*  SelectLabel                                                        */
/* ------------------------------------------------------------------ */

function SelectLabel({
  className,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.GroupLabel>) {
  return (
    <SelectPrimitive.GroupLabel
      data-slot="select-label"
      className={cn(
        "select-label px-[var(--layout-padding-md)] py-[var(--layout-padding-sm)] text-content-caption font-accent",
        className
      )}
      {...props}
    />
  )
}

/* ------------------------------------------------------------------ */
/*  SelectSeparator                                                    */
/* ------------------------------------------------------------------ */

function SelectSeparator({
  className,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.Separator>) {
  return (
    <SelectPrimitive.Separator
      data-slot="select-separator"
      className={cn("select-separator my-[var(--layout-gap-xs)]", className)}
      {...props}
    />
  )
}

export {
  Select,
  SelectGroup,
  SelectValue,
  SelectTrigger,
  SelectContent,
  SelectItem,
  SelectLabel,
  SelectSeparator,
  selectTriggerVariants,
}

/* ================================================================
 * SELECT — Styles
 * Structure (flex, gap, padding, radius) lives in select.tsx via cva.
 * Theming (colors, borders, focus ring) lives here via tokens.
 * ================================================================ */

/* --------------------------------
 * Trigger — base
 * -------------------------------- */
.select-trigger {
  background: var(--background-neutral-faint-default);
  border: var(--layout-border-thin) solid var(--border-default);
  color: var(--text-base-strong);
  cursor: pointer;
}

@media (prefers-reduced-motion: no-preference) {
  .select-trigger {
    transition:
      border-color 150ms ease,
      box-shadow 150ms ease;
  }
}

.select-trigger:hover {
  background: var(--background-neutral-faint-hover);
}

.select-trigger:focus-visible,
.select-trigger[data-popup-open] {
  outline: none;
  box-shadow: 0 0 0 2px var(--shadow-brand-moderate);
}

/* --------------------------------
 * Trigger — placeholder
 * -------------------------------- */
.select-trigger [data-placeholder] {
  color: var(--text-base-moderate);
}

/* --------------------------------
 * Trigger — disabled
 * -------------------------------- */
.select-trigger[data-disabled] {
  background: var(--background-disabled);
  color: var(--text-disabled);
  cursor: not-allowed;
  pointer-events: none;
}

.select-trigger[data-disabled] .select-chevron {
  color: var(--text-disabled);
}

/* --------------------------------
 * Trigger — destructive variant
 * -------------------------------- */
.select-trigger-destructive {
  border-color: var(--border-danger-strong);
}

.select-trigger-destructive:focus-visible,
.select-trigger-destructive[data-popup-open] {
  box-shadow: 0 0 0 2px var(--shadow-danger-moderate);
}

/* --------------------------------
 * Trigger — success variant
 * -------------------------------- */
.select-trigger-success {
  border-color: var(--border-success-strong);
}

.select-trigger-success:focus-visible,
.select-trigger-success[data-popup-open] {
  box-shadow: 0 0 0 2px var(--shadow-success-moderate);
}

/* --------------------------------
 * Chevron
 * -------------------------------- */
.select-chevron {
  color: var(--icon-neutral-moderate);
}

/* --------------------------------
 * Content panel
 * -------------------------------- */
.select-content {
  background: var(--background-neutral-faint-default);
  border: var(--layout-border-thin) solid var(--border-default);
}

/* --------------------------------
 * Item — base
 * -------------------------------- */
.select-item {
  color: var(--text-base-strong);
  cursor: pointer;
}

@media (prefers-reduced-motion: no-preference) {
  .select-item {
    transition:
      background 150ms ease,
      color 150ms ease;
  }
}

.select-item[data-highlighted] {
  background: var(--background-neutral-faint-hover);
  outline: none;
}

.select-item:focus-visible {
  background: var(--background-neutral-faint-hover);
  outline: none;
}

/* --------------------------------
 * Item — disabled
 * -------------------------------- */
.select-item[data-disabled] {
  color: var(--text-disabled);
  cursor: not-allowed;
  pointer-events: none;
}

/* --------------------------------
 * Item indicator (check)
 * -------------------------------- */
.select-item-indicator {
  color: var(--icon-brand-moderate);
}

/* --------------------------------
 * Label (group header)
 * -------------------------------- */
.select-label {
  color: var(--text-base-moderate);
}

/* --------------------------------
 * Content scrollbar
 * -------------------------------- */
.select-content {
  scrollbar-width: thin;
  scrollbar-color: var(--border-default) transparent;
}

.select-content::-webkit-scrollbar {
  width: 6px;
}

.select-content::-webkit-scrollbar-track {
  background: transparent;
}

.select-content::-webkit-scrollbar-thumb {
  background: var(--border-default);
  border-radius: var(--layout-radius-full);
}

/* --------------------------------
 * Separator
 * -------------------------------- */
.select-separator {
  border-top: var(--layout-border-thin) solid var(--border-default);
}
